/* Read-only geometry reservation diagnostic. No RGB/reference/shader input. */
#include "ayatsuri/compact_opaque.h"
#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <math.h>
#include <assert.h>
#include <time.h>
#include <string.h>
typedef struct {double a,b,c;int sign;int closed;} edge;
static edge make(const co_vertex*a,const co_vertex*b){double dx=(double)b->x-a->x,dy=(double)b->y-a->y;edge e={.sign=1,.closed=dy<0||(dy==0&&dx>0)};if(a->x>b->x||(a->x==b->x&&a->y>b->y)){const co_vertex*t=a;a=b;b=t;e.sign=-1;}e.a=(double)a->y-b->y;e.b=(double)b->x-a->x;e.c=((double)b->y-a->y)*a->x-((double)b->x-a->x)*a->y;return e;}
static uint64_t hash(const unsigned char*p,size_t n){uint64_t h=UINT64_C(14695981039346656037);while(n--){h^=*p++;h*=UINT64_C(1099511628211);}return h;}
static unsigned char snapshot[65536],mask[32400],hits[32400];
int main(int argc,char**argv){assert(argc==4);clock_t begin=clock();FILE*f=fopen(argv[1],"rb");assert(f);size_t n=fread(snapshot,1,sizeof snapshot,f);assert(fgetc(f)==EOF&&n==64208);fclose(f);f=fopen(argv[2],"rb");assert(f&&fread(mask,1,sizeof mask,f)==sizeof mask&&fgetc(f)==EOF);fclose(f);unsigned targets=0;for(unsigned i=0;i<32400;i++){assert(mask[i]<=1);targets+=mask[i];}double q=strtod(argv[3],NULL);assert(q==.25||q==0x1.272062ae104d0p-2);uint64_t records=0,triangles=0,bbox=0,targettests=0,edges=0,stores=0;unsigned count[4]={0};
 for(unsigned sample=0;sample<4;sample++){double dx=(sample&1)?q:-q,dy=(sample&2)?q:-q;size_t at=416;while(at<n){co_view v;assert(co_read(snapshot+at,n-at,&v));records++;for(unsigned face=0;face<v.triangle_count;face++){triangles++;uint8_t ix[3];co_vertex p[3];bool back;assert(co_triangle_at(&v,face,ix)&&co_triangle_side(&v,face,&back));for(unsigned j=0;j<3;j++)assert(co_vertex_at_side(&v,ix[j],back,p+j));double area=((double)p[1].x-p[0].x)*((double)p[2].y-p[0].y)-((double)p[1].y-p[0].y)*((double)p[2].x-p[0].x);assert(area>1e-5&&isfinite(area));edge e[3]={make(p+1,p+2),make(p+2,p),make(p,p+1)};int l=(int)ceil(fmin(p[0].x,fmin(p[1].x,p[2].x))-dx),r=(int)floor(fmax(p[0].x,fmax(p[1].x,p[2].x))-dx),t=(int)ceil(fmin(p[0].y,fmin(p[1].y,p[2].y))-dy),b=(int)floor(fmax(p[0].y,fmax(p[1].y,p[2].y))-dy);if(l<0)l=0;if(r>239)r=239;if(t<0)t=0;if(b>134)b=134;for(int y=t;y<=b;y++)for(int x=l;x<=r;x++){bbox++;unsigned pos=y*240+x;if(!mask[pos])continue;targettests++;double ev[3];bool in=true;for(unsigned k=0;k<3;k++){edges++;double a=e[k].sign*(e[k].a*(x+dx)+e[k].b*(y+dy)+e[k].c);ev[k]=a;if(a<0||(a==0&&!e[k].closed))in=false;}if(in){double inv=1/area;float depth=(float)((ev[0]*inv)*p[0].depth+(ev[1]*inv)*p[1].depth+(ev[2]*inv)*p[2].depth);assert(isfinite(depth));hits[pos]|=(1u<<sample);stores++;}}}at+=v.size;}assert(at==n);}
 for(unsigned i=0;i<32400;i++)for(unsigned j=0;j<4;j++)count[j]+=(hits[i]>>j)&1u;
 uint64_t snapshotHash=hash(snapshot,n),targetHash=hash(mask,sizeof mask);double seconds=(double)(clock()-begin)/CLOCKS_PER_SEC;
 printf("{\"snapshotFNV\":\"%016llx\",\"targetFNV\":\"%016llx\",\"targets\":%u,\"offset\":%.17g,\"sampleHits\":[%u,%u,%u,%u],\"totalHits\":%u,\"records\":%llu,\"triangles\":%llu,\"bboxVisits\":%llu,\"targetTests\":%llu,\"edgeTests\":%llu,\"coverageStores\":%llu,\"finalBitTests\":129600,\"staticScratchBytes\":%zu,\"cpuSeconds\":%.9g,\"noShaderOrReferenceRead\":true}\n",(unsigned long long)snapshotHash,(unsigned long long)targetHash,targets,q,count[0],count[1],count[2],count[3],count[0]+count[1]+count[2]+count[3],(unsigned long long)records,(unsigned long long)triangles,(unsigned long long)bbox,(unsigned long long)targettests,(unsigned long long)edges,(unsigned long long)stores,sizeof snapshot+sizeof mask+sizeof hits,seconds);}
